<!DOCTYPE html><html lang="en" data-theme="dark"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>500 - Server Error</title>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;600;700&display=swap" rel="stylesheet">
<link href="/public/css/app.css" rel="stylesheet"><style>.error-page{min-height:100vh;display:flex;align-items:center;justify-content:center;text-align:center;background:var(--bg-primary)}.error-code{font-size:8rem;font-weight:700;background:linear-gradient(135deg,#ef4444,#f59e0b);-webkit-background-clip:text;-webkit-text-fill-color:transparent;line-height:1}</style>
</head><body><div class="error-page"><div><div class="error-code">500</div><h2 style="color:var(--text-primary)">Server Error</h2><p style="color:var(--text-secondary);max-width:400px;margin:1rem auto">Something went wrong on our end. Please try again later.</p><a href="/dashboard" class="btn btn-primary btn-lg mt-3"><i class="bi bi-arrow-left"></i> Back to Dashboard</a></div></div></body></html>
